import numpy as np


def feature(neighbor_colors, adjacency, degree, color_sizes):
    """DSATUR saturation: number of distinct colours among a candidate's coloured neighbours, divided by the colours used so far."""
    k = neighbor_colors.shape[0]
    c = neighbor_colors.shape[1]
    if c == 0:
        return np.zeros(k, dtype=float)
    distinct = (neighbor_colors > 0).sum(axis=1).astype(float)
    return distinct / float(c)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Index of the candidate's first free existing colour, or c if none is free, divided by c."""
    k = neighbor_colors.shape[0]
    c = neighbor_colors.shape[1]
    if c == 0:
        return np.zeros(k)
    free = (neighbor_colors == 0)
    has_free = free.any(axis=1)
    first_free = free.argmax(axis=1)
    idx = np.where(has_free, first_free, c)
    return idx.astype(float) / float(c)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Degree of each candidate inside the still-uncoloured subgraph, divided by max(k-1, 1)."""
    k = adjacency.shape[0]
    if k == 0:
        return np.zeros(0)
    udeg = adjacency.sum(axis=1).astype(float)
    return udeg / max(k - 1, 1)
